// Builds the site's generated files from the parsed standard:
//   docs/assets/principles-data.js  data for the principles wheel and carousel
//   docs/principles/<slug>.html      one static page per principle, with every practice that breaks it
// Run through scripts/build-catalog.mjs, so the site never drifts from OPEN-ETHICS-STANDARD.md.
import { mkdir, writeFile } from "node:fs/promises";
import { resolve } from "node:path";

const STANDARD = "https://github.com/ike5/open-ethics-standard/blob/main/OPEN-ETHICS-STANDARD.md";
export const principleSlug = (name) => name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
const esc = (value) => String(value ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
const num = (label) => label.match(/^[\d.]+/)[0];
const strip = (label) => label.replace(/^[\d.]+\s*/, "");
const anchor = (label) => "s" + num(label).replace(/\./g, "-");
const two = (n) => String(n).padStart(2, "0");

export async function buildSite({ root, version, updated, principles, practices }) {
  const data = principles.map((principle) => {
    const tagged = practices.filter((item) => item.principles.includes(principle.name));
    const areas = [];
    for (const item of tagged) {
      let area = areas.find((entry) => entry.category === item.category);
      if (!area) areas.push(area = { category: item.category, count: 0, anchor: anchor(item.subsection) });
      area.count++;
    }
    areas.sort((a, b) => Number.parseInt(a.category, 10) - Number.parseInt(b.category, 10));
    return { ...principle, slug: principleSlug(principle.name), practices: tagged.length, areas };
  });
  await writeFile(resolve(root, "docs/assets/principles-data.js"),
    "// Generated by scripts/build-site.mjs from OPEN-ETHICS-STANDARD.md. Do not edit.\nwindow.OES_DATA = " + JSON.stringify({ version, updated, total: practices.length, principles: data }) + ";\n");
  const dir = resolve(root, "docs/principles");
  await mkdir(dir, { recursive: true });
  for (const [index, principle] of data.entries()) {
    await writeFile(resolve(dir, `${principle.slug}.html`), principlePage({ index, principle, data, practices, version }));
  }
}

function principlePage({ index, principle, data, practices, version }) {
  const tagged = practices.filter((item) => item.principles.includes(principle.name));
  const subsections = [];
  for (const item of tagged) {
    let sub = subsections.find((entry) => entry.label === item.subsection);
    if (!sub) subsections.push(sub = { label: item.subsection, category: item.category, principles: item.principles, items: [] });
    sub.items.push(item);
  }
  const pill = (name, on) => `<a class="pp${on ? " on" : ""}" href="${principleSlug(name)}.html">${on ? "" : "+ "}${esc(name)}</a>`;
  const others = (sub) => sub.principles.filter((name) => name !== principle.name);
  const grid = subsections.map((sub) => `<a class="sub" href="#${anchor(sub.label)}"><span class="sn">${esc(num(sub.label))}</span><span class="st">${esc(strip(sub.label))}</span>${others(sub).map((name) => `<span class="co">+ ${esc(name)}</span>`).join("")}<span class="sc">${sub.items.length}</span></a>`).join("\n        ");
  const tables = subsections.map((sub, i) => `
      <details class="block" id="${anchor(sub.label)}"${i < 3 ? " open" : ""}>
        <summary><h3><span class="sn">${esc(num(sub.label))}</span> ${esc(strip(sub.label))} <small>· ${sub.items.length} practice${sub.items.length === 1 ? "" : "s"}</small></h3><span class="pills">${pill(principle.name, true)}${others(sub).map((name) => pill(name, false)).join("")}</span><span class="chev" aria-hidden="true"></span></summary>
        <div class="scroll"><table>
          <thead><tr><th scope="col">§</th><th scope="col">Practice</th><th scope="col">Description</th><th scope="col">Seen in</th></tr></thead>
          <tbody>
${sub.items.map((item) => `            <tr><td class="id"><a href="${STANDARD}#L${item.sourceLine}">${esc(item.id)}</a></td><td class="pt">${esc(item.title)}</td><td>${esc(item.description)}</td><td class="dm">${esc(item.domains)}</td></tr>`).join("\n")}
          </tbody>
        </table></div>
      </details>`).join("");
  const switcher = data.map((p, i) => `<a href="${p.slug}.html"${i === index ? ' aria-current="page"' : ""}>${two(i + 1)} ${esc(p.name)}</a>`).join("");
  const prev = data[(index + data.length - 1) % data.length], next = data[(index + 1) % data.length];
  return `<!doctype html>
<!-- Generated by scripts/build-site.mjs from OPEN-ETHICS-STANDARD.md. Do not edit. -->
<html lang="en">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
  <meta name="theme-color" content="#f7f6f2"><meta name="description" content="${esc(principle.name)}: ${esc(principle.statement)} The ${tagged.length} practices in the Open Ethics Standard that break it.">
  <meta property="og:title" content="${esc(principle.name)} · Open Ethics Standard"><meta property="og:description" content="${esc(principle.statement)}"><meta property="og:image" content="https://ike5.github.io/open-ethics-standard/assets/report.png"><meta property="og:url" content="https://ike5.github.io/open-ethics-standard/principles/${principle.slug}.html"><meta name="twitter:card" content="summary_large_image">
  <link rel="icon" href="data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 32 32%22%3E%3Crect width=%2232%22 height=%2232%22 rx=%228%22 fill=%22%23d8f36a%22/%3E%3Ctext x=%2216%22 y=%2223%22 text-anchor=%22middle%22 font-family=%22Arial%22 font-weight=%22800%22 font-size=%2219%22 fill=%22%2317201d%22%3EO%3C/text%3E%3C/svg%3E">
  <title>${esc(principle.name)} · Open Ethics Standard</title>
  <link rel="stylesheet" href="../assets/site.css">
  <link rel="stylesheet" href="../assets/principle.css">
</head>
<body><a class="skip" href="#main">Skip to content</a>
  <header class="wrap header"><a class="brand" href="../index.html"><span class="mark">O</span><span>Open Ethics Standard</span></a><nav class="nav" aria-label="Main navigation"><a href="../principles.html">Principles</a><a href="honesty.html" aria-current="page">Practices</a><a href="../mcp.html">MCP</a><a class="github" href="https://github.com/ike5/open-ethics-standard">GitHub ↗</a></nav></header>
  <main id="main" class="wrap">
    <nav class="crumbs" aria-label="Breadcrumb"><a href="../principles.html">Principles</a> <span aria-hidden="true">/</span> <span aria-current="page">${esc(principle.name)}</span></nav>
    <nav class="switch" aria-label="The eight principles">${switcher}</nav>
    <section class="intro">
      <p class="kicker">Principle ${two(index + 1)} of ${data.length}</p>
      <h1>${esc(principle.name)}</h1>
      <p class="statement">${esc(principle.statement)}</p>
    </section>
    <section class="cards">
      <div class="card"><h2>Protects</h2><p>${esc(principle.protects)}</p></div>
      <div class="card"><h2>Why it matters</h2><p>${esc(principle.why)}</p></div>
      <div class="card"><h2>Covers</h2><p>${esc(principle.covers.charAt(0).toUpperCase() + principle.covers.slice(1))}</p></div>
    </section>
    <section class="breaks">
      <div class="head"><h2>Practices that break it</h2><p>${subsections.length} subsections · ${tagged.length} practices</p></div>
      <div class="subs">
        ${grid}
      </div>
    </section>
    <section class="tables">
      <h2>The same principle, across industries</h2>
      <p class="lead">Every practice above, as it reads in the catalog. Numbers link to the standard.</p>${tables}
    </section>
    <nav class="pager" aria-label="Other principles"><a href="${prev.slug}.html">← ${esc(prev.name)}</a><a href="${next.slug}.html">${esc(next.name)} →</a></nav>
  </main>
  <footer class="wrap footer"><span>Open Ethics Standard · version ${esc(version)}<br>Privacy: this site uses no cookies, analytics, or third-party resources. It is hosted on GitHub Pages, which logs requests under the <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub Privacy Statement</a>.</span><span><a href="../index.html">Home</a> · <a href="../principles.html">Principles</a> · <a href="../mcp.html">MCP</a> · <a href="${STANDARD}">The Standard</a></span></footer>
</body></html>
`;
}
